package com.vidyavedika.auth.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="users", indexes=@Index(name="idx_users_email", columnList="email", unique=true))
public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String email; @Column(nullable=false) private String password; @Column(nullable=false) private String name; @Enumerated(EnumType.STRING) @Column(nullable=false) private Role role=Role.USER; @Column(nullable=false) private boolean active=true; @Column(nullable=false) private Instant createdAt=Instant.now(); public Long getId(){return id;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public String getName(){return name;} public void setName(String v){name=v;} public Role getRole(){return role;} public void setRole(Role v){role=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} }
